<template>
  <section class="contact-list">
    <header><h2>{{ $t('expertWorkspace.customerAccess') }}</h2><label class="search"><span aria-hidden="true">⌕</span><input v-model="search" type="search" :placeholder="$t('expertWorkspace.search')" :aria-label="$t('expertWorkspace.search')" /></label><div class="filters" :aria-label="$t('expertWorkspace.customerAccess')"><button v-for="item in filters" :key="item" type="button" :aria-pressed="filter === item" @click="filter = item">{{ $t('expertWorkspace.' + item) }}<span>{{ count(item) }}</span></button></div></header>
    <div class="contact-rows"><p v-if="!rows.length" class="empty" role="status">{{ $t(search ? 'expertWorkspace.noMatches' : 'expertWorkspace.noRequests') }}</p><div v-for="request in rows" :key="request.request_id" class="contact" :class="{ selected: selectedId === request.request_id, unread: unreadCounts[request.request_id], 'has-new': newRequests[request.request_id] }"><button type="button" class="contact-main" :aria-pressed="selectedId === request.request_id" :disabled="busy || request.status === 'queued'" @click="$emit('select', request)"><span class="avatar" aria-hidden="true">{{ title(request).slice(0,1) }}</span><span class="contact-copy"><span class="contact-title"><strong>{{ title(request) }}</strong><span v-if="unreadCounts[request.request_id]" class="contact-unread" :aria-label="$t('supportNotifications.unreadCount', { count: unreadCounts[request.request_id] })">{{ unreadCounts[request.request_id] > 99 ? '99+' : unreadCounts[request.request_id] }}</span><span v-else-if="newRequests[request.request_id]" class="contact-new">{{ $t('supportNotifications.new') }}</span></span><small class="contact-preview" :title="preview(request) || request.request_id">{{ preview(request) || request.request_id }}</small><span class="contact-status"><span :class="{ waiting: request.status === 'queued' }">{{ $t('support.' + request.status) }}</span><time>{{ shortDate(activityTime(request, activity)) }}</time></span></span></button><button v-if="request.status === 'queued'" type="button" class="claim" :disabled="!accepting || busy" @click="$emit('claim', request)"><LegacyIcon class="el-icon-headset" />{{ $t('support.claim') }}</button></div></div>
    <footer><span>{{ $t('expertWorkspace.queueHint') }}</span><button type="button" :disabled="refreshing" :aria-label="$t('expertWorkspace.refreshQueue')" @click="$emit('refresh')"><LegacyIcon :class="refreshing ? 'el-icon-loading' : 'el-icon-refresh-right'" />{{ $t('support.refresh') }}</button></footer>
  </section>
</template>
<script>
import { activityTime, latestContacts } from '../../support/activity.mjs';
export default {
  name:'ExpertContactList', props:{ assigned:{type:Array,default:()=>[]}, queue:{type:Array,default:()=>[]}, titles:{type:Object,default:()=>({})}, selectedId:{type:String,default:''}, unreadCounts:{type:Object,default:()=>({})}, newRequests:{type:Object,default:()=>({})}, activity:{type:Object,default:()=>({})}, accepting:Boolean, busy:Boolean, refreshing:Boolean }, emits:['select','claim','refresh'], data:()=>({ search:'', filter:'all', filters:['all','waiting','active','history'] }),
  computed:{ requests(){ const unique=new Map(); for(const request of [...this.assigned,...this.queue]) if(!unique.has(request.request_id)) unique.set(request.request_id,request); return [...unique.values()]; }, rows(){ const query=this.search.trim().toLocaleLowerCase(); return latestContacts(this.requests, this.activity).filter(request=>this.matches(request,this.filter)&&[this.title(request),request.request_id,request.conversation_id].join(' ').toLocaleLowerCase().includes(query)); } },
  methods:{ activityTime, preview(request){const preview=this.activity[request.request_id]?.preview;return preview ? (preview.type === 'text' ? preview.text : this.$t('supportNotifications.preview_' + preview.type)) : '';}, title(request){ return this.titles[request.conversation_id] || this.activity[request.request_id]?.title || this.$t('support.consultation'); }, matches(request,filter){ return filter==='all'||(filter==='waiting'?request.status==='queued':filter==='active'?request.status==='active':!['active','queued'].includes(request.status)); }, count(filter){ return latestContacts(this.requests, this.activity).filter(request=>this.matches(request,filter)).length; }, shortDate(value){ if(!value)return ''; const date=new Date(value); return Number.isNaN(date.getTime())?'':date.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}); } },
};
</script>
<style scoped>
.contact-title{display:flex;align-items:center;gap:6px;min-width:0}.contact-title strong{min-width:0;flex:1}.contact-unread,.contact-new{flex:none;min-width:20px;height:20px;line-height:20px;padding:0 5px;border-radius:10px;background:var(--el-color-danger);color:white;font-size:var(--admin-font-xs);text-align:center}.contact-new{border-radius:4px}
.contact-list { display:flex; flex-direction:column; height:100%; min-height:0; }.contact-list header { padding:20px 14px 0; flex:none; }.contact-list h2 { font-size:var(--admin-font-title); margin:0 0 18px; }.search { display:flex; align-items:center; gap:7px; border:1px solid var(--admin-border, #e5e9f0); border-radius:8px; padding:0 10px; }.search span { color:var(--el-text-color-secondary, #909399); font-size:var(--admin-font-xl); }.search input { background:transparent; border:0; outline:0; min-width:0; width:100%; height:42px; font:inherit; color:var(--admin-text, #253247); font-size:var(--admin-font-xs); }.search:focus-within { outline:2px solid var(--el-color-primary-light-3, #79bbff); }.filters { display:flex; margin-top:12px; border-bottom:1px solid var(--admin-border, #e5e9f0); }.filters button { flex:1; min-width:0; padding:12px 0; background:none; border:0; border-bottom:3px solid transparent; color:var(--el-text-color-secondary, #909399); font-size:var(--admin-font-xs); }.filters button span { display:block; font-size:var(--admin-font-xs); margin-top:4px; }.filters button[aria-pressed=true] { color:var(--el-color-primary, #409eff); border-bottom-color:var(--el-color-primary, #409eff); font-weight:650; }.contact-rows { flex:1; min-height:0; overflow:auto; overscroll-behavior:contain; }.contact { position:relative; border-left:3px solid transparent; border-bottom:1px solid var(--admin-border, #e5e9f0); padding:0 11px; }.contact.unread:not(.selected),.contact.has-new:not(.selected) { background:var(--el-color-primary-light-9); border-left-color:var(--el-color-danger); }.contact.unread .contact-title strong { font-weight:700; }.contact.selected { background:var(--el-color-primary-light-9, #ecf5ff); border-left-color:var(--el-color-primary, #409eff); }.contact-main { display:flex; align-items:center; gap:9px; width:100%; text-align:left; padding:18px 0; background:transparent; border:0; color:var(--admin-text, #253247); }.contact-main:disabled { opacity:1; }.contact-copy { display:grid; gap:6px; flex:1; min-width:0; }.contact-copy strong,.contact-copy small { white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }.contact-copy strong { font-size:var(--admin-font-base); }.contact-copy small { font-size:var(--admin-font-xs); color:var(--el-text-color-secondary, #909399); }.avatar { width:40px; height:40px; border-radius:50%; display:flex; align-items:center; justify-content:center; background:var(--el-color-primary-light-9, #ecf5ff); color:var(--el-color-primary, #409eff); font-size:var(--admin-font-lg); flex:none; }.contact-status { display:flex; justify-content:space-between; gap:5px; font-size:var(--admin-font-xs); color:var(--el-text-color-secondary, #909399); }.contact-status .waiting { color:var(--el-color-primary, #409eff); }.contact-status time { font-size:var(--admin-font-xs); }.claim { width:100%; margin:-5px 0 12px; border:1px solid var(--admin-border, #e5e9f0); border-radius:6px; padding:7px; background:var(--el-color-primary-light-9, #ecf5ff); color:var(--el-color-primary, #409eff); }.empty { padding:28px 16px; font-size:var(--admin-font-base); color:var(--el-text-color-secondary, #909399); line-height:1.8; text-align:center; }footer { border-top:1px solid var(--admin-border, #e5e9f0); padding:14px; display:grid; gap:10px; color:var(--el-text-color-secondary, #909399); font-size:var(--admin-font-xs); }footer button { border:1px solid var(--admin-border, #e5e9f0); padding:9px; border-radius:6px; color:var(--el-color-primary, #409eff); background:white; }button { font:inherit; cursor:pointer; }button:disabled { cursor:not-allowed; opacity:.5; }button:focus-visible { outline:3px solid var(--el-color-primary-light-3, #79bbff); outline-offset:2px; }

.claim { display:flex; align-items:center; justify-content:center; gap:6px; font-weight:600; color:var(--el-color-success-dark-2,#529b2e); background:var(--el-color-success-light-9,#f0f9eb); border-color:var(--el-color-success-light-5,#b3e19d); }
.claim:not(:disabled):hover { background:var(--el-color-success-light-8,#e1f3d8); border-color:var(--el-color-success); }
footer button { display:flex; align-items:center; justify-content:center; gap:6px; background:var(--el-color-primary-light-9,#ecf5ff); border-color:var(--el-color-primary-light-5,#a0cfff); }
</style>
